import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { parseGameData } from "../src/data.ts";

// The synthetic fixture is generated by tools/synthetic/make_fixtures.py.
const url = new URL("../../fixtures/synthetic/gamedata.json", import.meta.url);

test("synthetic gamedata fixture matches the loader schema", () => {
  const json = JSON.parse(readFileSync(url, "utf8"));
  assert.match(json._notice, /SYNTHETIC/);
  const d = parseGameData(json);
  assert.equal(d.rngTable.length, 64);
  assert.equal(d.rivals.length, 30);
});
